import{_ as s,o as r,c as t,a2 as n}from"./chunks/framework.Zh78JZbW.js";const p=JSON.parse('{"title":"Gérer les instances","description":"","frontmatter":{},"headers":[],"relativePath":"guide/instances.md","filePath":"guide/instances.md"}'),a={name:"guide/instances.md"};function o(i,e,l,c,u,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="gerer-les-instances" tabindex="-1">Gérer les instances <a class="header-anchor" href="#gerer-les-instances" aria-label="Permalink to &quot;Gérer les instances&quot;">​</a></h1><p>Le bouton <strong>⚙ Gérer</strong>, situé à côté du nom de l&#39;instance (ou accessible par un clic droit dans la colonne de gauche), regroupe les réglages suivants :</p><ul><li><strong>Nom</strong> : renommer l&#39;instance.</li><li><strong>RAM</strong> : la mémoire attribuée au jeu. 4 Go suffisent dans la plupart des cas, 6 à 8 Go pour un modpack volumineux. Ne dépassez pas la moitié de la mémoire de votre ordinateur, et ne modifiez pas ce réglage sans raison.</li><li><strong>Version du loader</strong> : conservez « dernière version stable ». Kodus propose également la mise à jour du loader sur la page de l&#39;instance.</li><li><strong>Skins Kodus</strong> : affichage des skins dans cette instance (option à laisser cochée).</li><li><strong>Paramètres liés</strong> : décochez pour que cette instance garde ses propres réglages (voir ci-dessous).</li><li><strong>Ouvrir le dossier</strong> : accès au dossier de l&#39;instance (mondes, mods, captures…). Son emplacement est indiqué dans la fenêtre ; il se choisit à la création de l&#39;instance.</li><li><strong>Dupliquer</strong> : crée une copie complète, idéale pour tester des mods sans risque pour votre partie.</li><li><strong>Supprimer</strong> : l&#39;instance est placée dans la corbeille et reste récupérable.</li></ul><p>Ces actions ne sont pas disponibles pendant que l&#39;instance est en cours d&#39;exécution : fermez le jeu au préalable.</p><h2 id="parametres-lies" tabindex="-1">Paramètres liés <a class="header-anchor" href="#parametres-lies" aria-label="Permalink to &quot;Paramètres liés&quot;">​</a></h2><p>Pour retrouver vos touches, vos graphismes ou votre son dans toutes vos instances, ouvrez <strong>Paramètres</strong> → onglet <strong>Jeu</strong> → <strong>Paramètres du jeu liés</strong> :</p><ol><li>Activez <strong>Garder les mêmes réglages Minecraft dans toutes mes instances</strong>.</li><li>Choisissez l&#39;instance dont les réglages servent de départ, puis cliquez sur <strong>Copier ses réglages</strong>.</li><li>Cochez ce qui doit être partagé : <strong>Touches</strong>, <strong>Souris et contrôles</strong>, <strong>Graphismes</strong>, <strong>Son</strong>, <strong>Chat et accessibilité</strong>, <strong>Langue</strong>.</li></ol><p>Les réglages liés sont appliqués à chaque lancement. Si vous les modifiez en jeu, ils sont repris pour les autres instances à la fermeture du jeu.</p><div class="info custom-block"><p class="custom-block-title">Non concernés</p><p>Les instances d&#39;avant Minecraft 1.13, les packs de ressources activés, et les réglages propres aux mods (Sodium, Iris, OptiFine…), enregistrés dans d&#39;autres fichiers.</p></div>',9)])])}const m=s(a,[["render",o]]);export{p as __pageData,m as default};
